# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
import logging
import time

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

# The enflame external toolchain (gcu-compiler-compile / the llvm-ir converter
# script) segfaults intermittently under high host load while compiling Triton
# kernels (compiler_problems P02 family).  Failed compiles are not cached, so
# re-attempting the launch recompiles and usually succeeds; once a kernel is
# compiled the retry is a no-op.  Same hardening as the sibling
# linalg_cholesky.py.
_COMPILE_RETRY_ATTEMPTS = 6
_COMPILE_RETRY_DELAY_S = 1.0


def _launch_retry(launch):
    for attempt in range(_COMPILE_RETRY_ATTEMPTS):
        try:
            return launch()
        except Exception:
            if attempt == _COMPILE_RETRY_ATTEMPTS - 1:
                raise
            time.sleep(_COMPILE_RETRY_DELAY_S)


# Define a fixed maximum matrix size we can handle
MAX_MATRIX_SIZE = 64


@libentry()
@triton.jit
def ldl_factor_kernel(
    A,
    LD,
    pivots,
    N,
    stride_a0,
    stride_a1,
    stride_a2,
    stride_ld0,
    stride_ld1,
    stride_ld2,
    MAX_SIZE: tl.constexpr,
):
    # Each program handles one matrix in the batch.
    batch_idx = tl.program_id(0)
    i = tl.arange(0, MAX_SIZE)[:, None]
    j = tl.arange(0, MAX_SIZE)[None, :]
    ii = tl.arange(0, MAX_SIZE)
    mask = (i < N) & (j < N)

    # Load the matrix and symmetrize it in-kernel: A_sym = (A + A^T) / 2 for
    # real dtypes (the only ones accepted below).  Averaging here removes two
    # extra device passes from the caller.
    a_ptr = A + batch_idx * stride_a0
    a = tl.load(a_ptr + i * stride_a1 + j * stride_a2, mask=mask, other=0.0)
    at = tl.load(a_ptr + j * stride_a1 + i * stride_a2, mask=mask, other=0.0)
    w = 0.5 * (a + at)

    # Right-looking LDL: the whole MAX_SIZE x MAX_SIZE block lives in registers,
    # so the k loop stays sequential but every step is a rank-1 update of the
    # trailing Schur complement plus one column extraction.
    #
    # Each step needs one axis-1 column extraction and one scalar reduction;
    # on GCU400 a cross-lane reduction costs ~1-4 us, so keeping exactly one
    # per step is what makes this kernel viable (the previous column-oriented
    # form needed four reductions per step and ran 2.9x slower).
    #
    # The finished column is committed straight to global memory instead of
    # being written back into the register tile: past columns are dead in the
    # tile afterwards, so this drops the per-step in-tile column write, the
    # running diagonal vector (dvec) and the whole epilogue combine pass
    # (the update may leave garbage in dead column k of the tile; it is never
    # read again).
    #
    # Output format (PyTorch style), written column by column:
    # - Diagonal LD[k,k] = D[k,k]
    # - Below diagonal LD[i,k] = L[i,k] for i > k
    # - Above diagonal LD[i,k] = 0
    ld_ptr = LD + batch_idx * stride_ld0
    inb = ii < N
    for k in range(0, N):
        # column k of the Schur complement (only i >= k is meaningful)
        colk = tl.sum(tl.where(j == k, w, 0.0), axis=1)
        dk = tl.sum(tl.where(ii == k, colk, 0.0))  # D[k,k] = W[k,k]
        # L[:,k] = W[i,k] / D[k,k] for i > k; D[k,k] on the diagonal; 0 above.
        ls = tl.where(ii > k, colk, 0.0)
        lcol = tl.where(ii == k, dk, ls / dk)
        # W22 -= D[k,k] * L21 * L21^T.  (D[k,k] * L21 == ls, and ls/lcol are
        # zero outside i,j > k, so no trailing-block mask is needed.)
        w = w - ls[:, None] * lcol[None, :]
        tl.store(ld_ptr + ii * stride_ld1 + k * stride_ld2, lcol, mask=inb)
    tl.store(pivots + batch_idx * N + ii, ii + 1, mask=inb)


def ldl_factor(A, *, hermitian=False):
    """
    Compute the LDL factorization of a symmetric/hermitian matrix.

    Returns a named tuple (LD, pivots) where:
    - LD is a compact representation of L and D matrices
    - pivots contains the pivot indices (1-indexed)

    This implements the standard LDL decomposition: A = L @ D @ L^T
    where L is unit lower triangular and D is diagonal.
    """
    if A.ndim < 2:
        raise ValueError("linalg_ldl_factor: A must be at least 2D")

    if A.shape[-2] != A.shape[-1]:
        raise ValueError("linalg_ldl_factor: matrix must be square")

    if A.dtype not in (torch.float32, torch.float64):
        raise TypeError("linalg_ldl_factor: only float32 and float64 are supported")

    batch_shape = A.shape[:-2]
    n = A.shape[-1]

    if n > MAX_MATRIX_SIZE:
        raise ValueError(
            f"linalg_ldl_factor: matrix size {n} exceeds maximum {MAX_MATRIX_SIZE}"
        )

    # The kernel symmetrizes the input itself (A + A^T) / 2; for the real
    # dtypes accepted above the hermitian conjugate is a plain transpose.
    A = A.contiguous()

    LD = torch.empty_like(A)
    pivots_shape = batch_shape + (n,)
    pivots = torch.empty(pivots_shape, dtype=torch.int32, device=A.device)

    logger.debug(
        "GEMS LDL_FACTOR, shape: %s, n: %d, hermitian: %s",
        A.shape,
        n,
        hermitian,
    )

    batch_size = 1
    for dim in batch_shape:
        batch_size *= dim

    grid = (batch_size,)

    with torch_device_fn.device(A.device):
        _launch_retry(
            lambda: ldl_factor_kernel[grid](
                A,
                LD,
                pivots,
                n,
                A.stride(0) if A.ndim > 2 else 0,
                A.stride(-2),
                A.stride(-1),
                LD.stride(0) if LD.ndim > 2 else 0,
                LD.stride(-2),
                LD.stride(-1),
                triton.next_power_of_2(n),
                num_warps=1,
            )
        )

    # Return as a named tuple manually
    return (LD, pivots)
